export function getCategoryIcon(catName: string, customIcons?: Record<string, string>): string {
  const clean = (catName || '').trim();
  if (!clean) return '📦';
  if (customIcons && customIcons[clean]) return customIcons[clean];
  if (customIcons) {
    const foundKey = Object.keys(customIcons).find(
      (k) => k.trim().toLowerCase() === clean.toLowerCase()
    );
    if (foundKey && customIcons[foundKey]) return customIcons[foundKey];
  }
  if (DEFAULT_CATEGORY_ICONS[clean]) return DEFAULT_CATEGORY_ICONS[clean];

  const lower = clean.toLowerCase();
  if (lower.includes('fruta') || lower.includes('manzana') || lower.includes('citric')) return '🍎';
  if (
    lower.includes('alimento') ||
    lower.includes('viver') ||
    lower.includes('víver') ||
    lower.includes('comida') ||
    lower.includes('grano') ||
    lower.includes('abasto') ||
    lower.includes('despensa')
  )
    return '🥫';
  if (
    lower.includes('bebida') ||
    lower.includes('refresco') ||
    lower.includes('jugo') ||
    lower.includes('licor') ||
    lower.includes('agua') ||
    lower.includes('cerveza')
  )
    return '🥤';
  if (
    lower.includes('carne') ||
    lower.includes('pollo') ||
    lower.includes('res') ||
    lower.includes('cerdo') ||
    lower.includes('charcuter') ||
    lower.includes('embutido') ||
    lower.includes('proteina')
  )
    return '🥩';
  if (lower.includes('lacteo') || lower.includes('lácteo') || lower.includes('queso') || lower.includes('leche'))
    return '🧀';
  if (lower.includes('verdura') || lower.includes('vegetal') || lower.includes('hortaliza')) return '🥦';
  if (lower.includes('pan') || lower.includes('pastel') || lower.includes('reposter')) return '🥖';
  if (lower.includes('dulce') || lower.includes('snack') || lower.includes('chucher') || lower.includes('galleta'))
    return '🍫';
  if (lower.includes('pescado') || lower.includes('marisco')) return '🐟';
  if (lower.includes('huevo') || lower.includes('granja')) return '🥚';
  if (lower.includes('limpieza') || lower.includes('aseo') || lower.includes('hogar')) return '🧹';
  if (lower.includes('higiene') || lower.includes('cuidado') || lower.includes('perfum')) return '🧴';
  if (lower.includes('mascota') || lower.includes('perro') || lower.includes('gato')) return '🐾';
  if (lower.includes('tecnolog') || lower.includes('electron') || lower.includes('celular')) return '📱';
  if (lower.includes('ropa') || lower.includes('calzado') || lower.includes('vestir')) return '👕';
  if (lower.includes('farmac') || lower.includes('salud') || lower.includes('medicin')) return '💊';
  return '📦';
}

export function detectProductAutoIcon(
  name: string,
  category: string,
  categoryIcons?: Record<string, string>
): string {
  const n = (name || '').toLowerCase();
  if (n.includes('café') || n.includes('cafe') || n.includes('nescaf')) return '☕';
  if (n.includes('harina') || n.includes('maíz') || n.includes('maiz')) return '🌽';
  if (n.includes('arroz')) return '🍚';
  if (n.includes('pasta') || n.includes('espagueti') || n.includes('fideo')) return '🍝';
  if (n.includes('pan ') || n.startsWith('pan') || n.includes('cachito') || n.includes('galleta')) return '🥖';
  if (n.includes('queso') || n.includes('cuajada')) return '🧀';
  if (n.includes('leche') || n.includes('yogurt') || n.includes('suero')) return '🥛';
  if (n.includes('mantequilla') || n.includes('margarina')) return '🧈';
  if (n.includes('huevo') || n.includes('cartón') || n.includes('carton')) return '🥚';
  if (n.includes('manzana')) return '🍎';
  if (n.includes('cambur') || n.includes('banana') || n.includes('plátano') || n.includes('platano')) return '🍌';
  if (n.includes('naranja') || n.includes('mandarina')) return '🍊';
  if (n.includes('fresa') || n.includes('mora') || n.includes('patilla') || n.includes('sandía')) return '🍓';
  if (n.includes('limón') || n.includes('limon') || n.includes('piña') || n.includes('pina') || n.includes('mango')) return '🍍';
  if (n.includes('aguacate')) return '🥑';
  if (n.includes('tomate') || n.includes('cebolla') || n.includes('pimentón') || n.includes('papa')) return '🍅';
  if (n.includes('zanahoria') || n.includes('lechuga') || n.includes('brócoli')) return '🥕';
  if (n.includes('carne') || n.includes('bistec') || n.includes('molida') || n.includes('solomo') || n.includes('costilla')) return '🥩';
  if (n.includes('pollo') || n.includes('pechuga') || n.includes('muslo') || n.includes('alita')) return '🍗';
  if (n.includes('cerdo') || n.includes('chuleta') || n.includes('tocineta') || n.includes('jamón') || n.includes('jamon') || n.includes('mortadela') || n.includes('salchicha')) return '🥓';
  if (n.includes('pescado') || n.includes('atún') || n.includes('atun') || n.includes('sardina')) return '🐟';
  if (n.includes('refresco') || n.includes('coca') || n.includes('pepsi') || n.includes('malta') || n.includes('soda') || n.includes('gaseosa')) return '🥤';
  if (n.includes('jugo') || n.includes('néctar') || n.includes('nectar') || n.includes('té') || n.includes('te ')) return '🧃';
  if (n.includes('agua') || n.includes('botellón') || n.includes('botellon')) return '💧';
  if (n.includes('cerveza') || n.includes('vino') || n.includes('ron') || n.includes('whisky')) return '🍺';
  if (n.includes('chocolate') || n.includes('dulce') || n.includes('caramelo') || n.includes('chupeta') || n.includes('snack') || n.includes('dorito') || n.includes('papita')) return '🍫';
  if (n.includes('aceite') || n.includes('mayonesa') || n.includes('salsa') || n.includes('vinagre')) return '🫙';
  if (n.includes('azúcar') || n.includes('azucar') || n.includes('sal')) return '🧂';
  if (n.includes('jabón') || n.includes('jabon') || n.includes('detergente') || n.includes('cloro') || n.includes('desinfectante')) return '🧹';
  if (n.includes('champú') || n.includes('champu') || n.includes('crema') || n.includes('papel') || n.includes('desodorante')) return '🧴';
  if (n.includes('teléfono') || n.includes('telefono') || n.includes('smartphone') || n.includes('celular') || n.includes('audífono') || n.includes('cargador')) return '📱';
  return getCategoryIcon(category, categoryIcons);
}

