export function ensureFivePanelCarts(rawCarts?: AppCart[]): AppCart[] {
  const base = Array.isArray(rawCarts) ? [...rawCarts.slice(0, 5)] : [];
  const usedIds = new Set(base.map((c) => c.id));
  while (base.length < 5) {
    const slotNum = base.length + 1;
    let candidateId = `c${slotNum}`;
    while (usedIds.has(candidateId)) {
      candidateId = `c${slotNum}_${Math.random().toString(36).slice(2, 5)}`;
    }
    usedIds.add(candidateId);
    base.push({
      id: candidateId,
      name: `Cliente ${slotNum}`,
      items: [],
    });
  }
  return base;
}

