export function generate16CharCode(): string {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  const block = () =>
    Array.from({ length: 4 }, () => chars.charAt(Math.floor(Math.random() * chars.length))).join(
      ''
    );
  return `${block()}-${block()}-${block()}-${block()}`;
}

export function extractTokenShortBlock(userToken?: string, ownerEmail?: string): string {
  const firstSegment = (userToken || '')
    .trim()
    .toUpperCase()
    .split('-')[0]
    ?.replace(/[^A-Z0-9]/g, '');
  if (firstSegment && firstSegment.length >= 4) {
    return firstSegment.slice(0, 4);
  }
  const cleaned = (userToken || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (cleaned.length >= 4) {
    return cleaned.slice(0, 4);
  }
  const emailClean = (ownerEmail || ADMIN_EMAIL).toUpperCase().replace(/[^A-Z0-9]/g, '');
  return (emailClean + 'TKN1').slice(0, 4);
}

export function computeDeterministic4Digits(seed: string): string {
  let hash = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    hash ^= seed.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  const num = Math.abs(hash) % 10000;
  return String(num).padStart(4, '0');
}

export function generateStoreOrBranchUniqueCode(opts: {
  type: 'tienda' | 'sucursal';
  typeIndex: number;
  userToken?: string;
  ownerEmail?: string;
  seedId?: string;
  randomDigits?: boolean;
}): string {
  const prefix = opts.type === 'sucursal' ? 'SUC' : 'TIEN';
  const idx = Math.max(1, opts.typeIndex || 1);
  const tokenPart = extractTokenShortBlock(opts.userToken, opts.ownerEmail);
  const digits = opts.randomDigits
    ? String(Math.floor(1000 + Math.random() * 9000))
    : computeDeterministic4Digits(
        `${(opts.ownerEmail || ADMIN_EMAIL).toLowerCase()}|${prefix}${idx}|${tokenPart}|${
          opts.seedId || 'default'
        }`
      );
  return `${prefix}${idx}-${tokenPart}-${digits}`;
}

