  // Theme Mode (Light / Dark) & Automatic Device-Time Dark Mode persisted in localStorage
  const evaluateThemeForDeviceHour = useCallback(
    (currentHour: number, startHour: number, endHour: number): 'dark' | 'light' => {
      if (startHour === endHour) return 'dark';
      if (startHour > endHour) {
        // Overnight schedule (e.g. 18:00 to 06:00)
        return currentHour >= startHour || currentHour < endHour ? 'dark' : 'light';
      }
      // Same-day schedule
      return currentHour >= startHour && currentHour < endHour ? 'dark' : 'light';
    },
    []
  );

  const [autoDarkByTime, setAutoDarkByTime] = useState<boolean>(() => {
    try {
      return localStorage.getItem('mi_tienda_auto_dark_by_time') === 'true';
    } catch {
      return false;
    }
  });

  const [autoDarkStartHour, setAutoDarkStartHour] = useState<number>(() => {
    try {
      const saved = parseInt(localStorage.getItem('mi_tienda_auto_dark_start_hour') || '18', 10);
      return !Number.isNaN(saved) && saved >= 0 && saved <= 23 ? saved : 18;
    } catch {
      return 18;
    }
  });

  const [autoDarkEndHour, setAutoDarkEndHour] = useState<number>(() => {
    try {
      const saved = parseInt(localStorage.getItem('mi_tienda_auto_dark_end_hour') || '6', 10);
      return !Number.isNaN(saved) && saved >= 0 && saved <= 23 ? saved : 6;
    } catch {
      return 6;
    }
  });

  const [deviceTimeDisplay, setDeviceTimeDisplay] = useState<string>(() =>
    new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
  );

  const [themeMode, setThemeMode] = useState<'dark' | 'light'>(() => {
    try {
      const isAuto = localStorage.getItem('mi_tienda_auto_dark_by_time') === 'true';
      if (isAuto) {
        const sH = parseInt(localStorage.getItem('mi_tienda_auto_dark_start_hour') || '18', 10);
        const eH = parseInt(localStorage.getItem('mi_tienda_auto_dark_end_hour') || '6', 10);
        const startHour = !Number.isNaN(sH) && sH >= 0 && sH <= 23 ? sH : 18;
        const endHour = !Number.isNaN(eH) && eH >= 0 && eH <= 23 ? eH : 6;
        const nowHour = new Date().getHours();
        if (startHour === endHour) return 'dark';
        if (startHour > endHour) {
          return nowHour >= startHour || nowHour < endHour ? 'dark' : 'light';
        }
        return nowHour >= startHour && nowHour < endHour ? 'dark' : 'light';
      }
      const saved = localStorage.getItem('mi_tienda_theme_mode');
      return saved === 'light' ? 'light' : 'dark';
    } catch {
      return 'dark';
    }
  });

  // Periodically check the user's device clock and apply automatic Dark/Light mode when enabled
  useEffect(() => {
    const syncDeviceClockAndTheme = () => {
      const now = new Date();
      setDeviceTimeDisplay(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
      if (autoDarkByTime) {
        const targetTheme = evaluateThemeForDeviceHour(
          now.getHours(),
          autoDarkStartHour,
          autoDarkEndHour
        );
        setThemeMode((prev) => {
          if (prev !== targetTheme) {
            try {
              localStorage.setItem('mi_tienda_theme_mode', targetTheme);
            } catch {
              // ignore storage errors
            }
          }
          return targetTheme;
        });
      }
    };

    syncDeviceClockAndTheme();
    const intervalId = window.setInterval(syncDeviceClockAndTheme, 30000);
    const handleVisibility = () => {
      if (document.visibilityState === 'visible') {
        syncDeviceClockAndTheme();
      }
    };
    document.addEventListener('visibilitychange', handleVisibility);

    return () => {
      window.clearInterval(intervalId);
      document.removeEventListener('visibilitychange', handleVisibility);
    };
  }, [autoDarkByTime, autoDarkStartHour, autoDarkEndHour, evaluateThemeForDeviceHour]);

  const handleToggleAutoDarkByTime = (enabled: boolean) => {
    setAutoDarkByTime(enabled);
    try {
      localStorage.setItem('mi_tienda_auto_dark_by_time', enabled ? 'true' : 'false');
    } catch {
      // ignore storage errors
    }
    if (enabled) {
      const nowHour = new Date().getHours();
      const scheduledTheme = evaluateThemeForDeviceHour(
        nowHour,
        autoDarkStartHour,
        autoDarkEndHour
      );
      setThemeMode(scheduledTheme);
      try {
        localStorage.setItem('mi_tienda_theme_mode', scheduledTheme);
      } catch {
        // ignore
      }
    }
  };

  const handleChangeAutoDarkSchedule = (startHour: number, endHour: number) => {
    setAutoDarkStartHour(startHour);
    setAutoDarkEndHour(endHour);
    try {
      localStorage.setItem('mi_tienda_auto_dark_start_hour', String(startHour));
      localStorage.setItem('mi_tienda_auto_dark_end_hour', String(endHour));
    } catch {
      // ignore storage errors
    }
    if (autoDarkByTime) {
      const scheduledTheme = evaluateThemeForDeviceHour(
        new Date().getHours(),
        startHour,
        endHour
      );
      setThemeMode(scheduledTheme);
      try {
        localStorage.setItem('mi_tienda_theme_mode', scheduledTheme);
      } catch {
        // ignore
      }
    }
  };

  const toggleThemeMode = () => {
    if (autoDarkByTime) {
      setAutoDarkByTime(false);
      try {
        localStorage.setItem('mi_tienda_auto_dark_by_time', 'false');
      } catch {
        // ignore
      }
    }
    setThemeMode((prev) => {
      const next = prev === 'dark' ? 'light' : 'dark';
      try {
        localStorage.setItem('mi_tienda_theme_mode', next);
      } catch {
        // ignore storage errors
      }
      showToast(
        next === 'light' ? '☀️ Tema Claro activado' : '🌙 Tema Oscuro activado',
        'info'
      );
      return next;
    });
  };

  // --- KIOSK MODE (CATÁLOGO VIRTUAL SEGURO EN PUNTO DE VENTA) ---
