  // Automatic Live Exchange Rates Fetcher for All World Currencies
  const fetchLiveExchangeRates = useCallback(
    async (notifyUser = false) => {
      setIsSyncingRates(true);
      const updatedMap: Record<string, number> = { ...DEFAULT_CURRENCY_RATES_USD };
      const updatedCrypto = {
        BTC: parseFloat(rateBTC) || 67500,
        BNB: parseFloat(rateBNB) || 590,
        USDT: 1.0,
        USDC: 1.0,
        ETH: parseFloat(rateETH) || 2650,
      };

      try {
        const res = await fetch('https://open.er-api.com/v6/latest/USD');
        if (res.ok) {
          const data = await res.json();
          if (data?.rates) {
            WORLD_CURRENCIES.forEach(({ code }) => {
              if (typeof data.rates[code] === 'number' && data.rates[code] > 0) {
                const isZeroDec =
                  code === 'COP' ||
                  code === 'CLP' ||
                  code === 'ARS' ||
                  code === 'PYG' ||
                  code === 'KRW' ||
                  code === 'IDR' ||
                  code === 'NGN';
                updatedMap[code] = Number(data.rates[code].toFixed(isZeroDec ? 0 : 2));
              }
            });
          }
        }
      } catch {
        // fallback to defaults if offline
      }

      try {
        const bcvRes = await fetch('https://ve.dolarapi.com/v1/dolares/oficial');
        if (bcvRes.ok) {
          const bcvData = await bcvRes.json();
          if (typeof bcvData?.promedio === 'number' && bcvData.promedio > 0) {
            updatedMap.VES = Number(bcvData.promedio.toFixed(2));
          }
        }
      } catch {
        // ignore if BCV endpoint unavailable
      }

      try {
        const binanceRes = await fetch(
          'https://api.binance.com/api/v3/ticker/price?symbols=%5B%22BTCUSDT%22,%22BNBUSDT%22,%22ETHUSDT%22%5D'
        );
        if (binanceRes.ok) {
          const tickers: Array<{ symbol: string; price: string }> = await binanceRes.json();
          tickers.forEach((t) => {
            const p = parseFloat(t.price);
            if (p > 0) {
              if (t.symbol === 'BTCUSDT') updatedCrypto.BTC = Number(p.toFixed(2));
              if (t.symbol === 'BNBUSDT') updatedCrypto.BNB = Number(p.toFixed(2));
              if (t.symbol === 'ETHUSDT') updatedCrypto.ETH = Number(p.toFixed(2));
            }
          });
        }
      } catch {
        // fallback crypto rates
      }

      setLiveRatesMap(updatedMap);
      const nowTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

      setAppState((prev) => {
        if (prev.rates.autoSync === false && !notifyUser) return prev;
        const refCurr = prev.rates.refCurrency || 'USD';
        const priCurr = prev.rates.primaryCurrency || 'VES';
        const secCurr = prev.rates.secondaryCurrency || 'COP';

        const nextRefVal = updatedMap[refCurr] ?? prev.rates.refUSD ?? 1.0;
        const nextPriVal = updatedMap[priCurr] ?? prev.rates.primaryRate;
        const nextSecVal = updatedMap[secCurr] ?? prev.rates.secondaryRate;

        setRateRefValue(String(nextRefVal));
        setRatePrimaryValue(String(nextPriVal));
        setRateSecondaryValue(String(nextSecVal));
        setRateBTC(String(updatedCrypto.BTC));
        setRateBNB(String(updatedCrypto.BNB));
        setRateETH(String(updatedCrypto.ETH));

        return {
          ...prev,
          rates: {
            ...prev.rates,
            refUSD: nextRefVal,
            primaryRate: nextPriVal,
            secondaryRate: nextSecVal,
            lastSyncAt: `Auto ${nowTime}`,
            crypto: updatedCrypto,
          },
        };
      });

      setIsSyncingRates(false);
      if (notifyUser) {
        showToast('¡Tasas sincronizadas automáticamente en tiempo real! ⚡');
      }
    },
    [rateBTC, rateBNB, rateETH]
  );

  useEffect(() => {
    fetchLiveExchangeRates(false);
    const interval = setInterval(() => {
      fetchLiveExchangeRates(false);
    }, 300000);
    return () => clearInterval(interval);
  }, []);

  // Automatically update rate and appState immediately when user selects a currency
