    setProdExpiry('');
    setProdDescription('');
    setProdImage('');
    setProdCustomIcon('');
    setProdShowCatalog(true);
    setProdTags([]);
    setProdCustomTagInput('');
    setShowModalCategoryEditor(false);
    setActiveModal('addProduct');
