    setProdMargin(String(prod.margin));
    setProdPrice(String(prod.price));
    setProdPromoPrice(
      typeof prod.promoPrice === 'number' && prod.promoPrice > 0 ? String(prod.promoPrice) : ''
    );
    setProdWholesaleMinQty(
      typeof prod.wholesaleMinQty === 'number' && prod.wholesaleMinQty > 0
        ? String(prod.wholesaleMinQty)
        : ''
    );
    setProdWholesalePrice(
      typeof prod.wholesalePrice === 'number' && prod.wholesalePrice > 0
        ? String(prod.wholesalePrice)
        : ''
    );
    setProdHasTax(Boolean(prod.hasTax && typeof prod.taxRatePct === 'number' && prod.taxRatePct > 0));
    setProdTaxLabel(prod.taxLabel || localStorage.getItem('nexo_checkout_tax_label') || 'IVA');
    setProdTaxRatePct(
      typeof prod.taxRatePct === 'number' && prod.taxRatePct > 0
        ? String(prod.taxRatePct)
        : localStorage.getItem('nexo_checkout_tax_rate') || '16'
    );
    setProdStock(String(prod.stock));
    setProdMin(String(prod.minStock));
    setProdBarcode(prod.barcode);
    setProdExpiry(prod.expiry || '');
