                            <input
                              type="checkbox"
                              id="global-auto-tax-toggle"
                              checked={rateAutoApplyTaxToNewProducts}
                              onChange={(e) =>
                                toggleGlobalAutoApplyTaxToNewProducts(e.target.checked)
                              }
                              className="w-4 h-4 mt-0.5 rounded accent-emerald-500 cursor-pointer shrink-0"
                            />
